adicionar_item_compra:
CREATE OR REPLACE FUNCTION public.adicionar_item_compra(_compra_id uuid, _produto_id uuid, _quantidade numeric, _custo_unitario numeric, _lote text DEFAULT NULL::text, _validade date DEFAULT NULL::date)
 RETURNS compra_itens
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  cmp public.compras;
  it public.compra_itens;
BEGIN
 -- compras_guard_231
 if not public.pode_rotina('compras_operar') then raise exception 'Operação de compras não liberada para seu perfil'; end if;

  if not public.can_stock(auth.uid()) and not public.can_finance(auth.uid()) then
    raise exception 'Sem permissao para alterar itens da compra';
  end if;

  select * into cmp from public.compras where id=_compra_id for update;
  if cmp.id is null then raise exception 'Compra nao encontrada'; end if;
  if cmp.centro_id is null or not public.usuario_pode_acessar_centro(cmp.centro_id) then
    raise exception 'Compra pertence a outro centro';
  end if;
  if cmp.status <> 'rascunho' then
    raise exception 'Itens nao podem ser alterados no status atual: %', cmp.status;
  end if;
  if not exists (select 1 from public.produtos p where p.id=_produto_id) then
    raise exception 'Produto nao encontrado';
  end if;
  if coalesce(_quantidade,0) <= 0 then raise exception 'Quantidade deve ser maior que zero'; end if;
  if coalesce(_custo_unitario,0) < 0 then raise exception 'Custo unitario invalido'; end if;

  insert into public.compra_itens(compra_id,produto_id,quantidade,custo_unitario,lote,validade)
  values(
    _compra_id,_produto_id,_quantidade,round(_custo_unitario,4),
    nullif(_lote,''),_validade
  )
  returning * into it;

  perform public.recalcular_compra(_compra_id);
  return it;
end;
$function$

atualizar_item_compra:
CREATE OR REPLACE FUNCTION public.atualizar_item_compra(_item_id uuid, _quantidade numeric, _custo_unitario numeric)
 RETURNS compra_itens
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  it public.compra_itens;
  cmp public.compras;
BEGIN
 -- compras_guard_231
 if not public.pode_rotina('compras_operar') then raise exception 'Operação de compras não liberada para seu perfil'; end if;

  if not public.can_stock(auth.uid()) and not public.can_finance(auth.uid()) then
    raise exception 'Sem permissao para alterar itens da compra';
  end if;

  select * into it from public.compra_itens where id=_item_id for update;
  if it.id is null then raise exception 'Item nao encontrado'; end if;
  select * into cmp from public.compras where id=it.compra_id for update;
  if cmp.id is null then raise exception 'Compra nao encontrada'; end if;
  if cmp.centro_id is null or not public.usuario_pode_acessar_centro(cmp.centro_id) then
    raise exception 'Compra pertence a outro centro';
  end if;
  if cmp.status <> 'rascunho' then
    raise exception 'Item nao pode ser alterado no status atual: %', cmp.status;
  end if;
  if coalesce(_quantidade,0) <= 0 then raise exception 'Quantidade deve ser maior que zero'; end if;
  if coalesce(_custo_unitario,0) < 0 then raise exception 'Custo unitario invalido'; end if;

  update public.compra_itens
  set quantidade=_quantidade,
      custo_unitario=round(_custo_unitario,4)
  where id=_item_id
  returning * into it;

  perform public.recalcular_compra(cmp.id);
  return it;
end;
$function$

compra_itens_total:
CREATE OR REPLACE FUNCTION public.compra_itens_total()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.total := round(new.quantidade * new.custo_unitario, 2);
  return new;
end;
$function$

receber_compra:
CREATE OR REPLACE FUNCTION public.receber_compra(_compra_id uuid)
 RETURNS compras
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  cmp public.compras;
  item record;
  n int;
  valor_parcela numeric(14,2);
  saldo numeric(14,2);
BEGIN
 -- compras_guard_231
 if not public.pode_rotina('compras_operar') then raise exception 'Operação de compras não liberada para seu perfil'; end if;

  if not public.can_stock(auth.uid()) and not public.can_finance(auth.uid()) then
    raise exception 'Sem permissão para receber compras';
  end if;

  select * into cmp from public.compras where id=_compra_id for update;
  if cmp.id is null then raise exception 'Compra não encontrada'; end if;
  if cmp.centro_id is null then raise exception 'Centro da compra obrigatório'; end if;
  if not public.usuario_pode_acessar_centro(cmp.centro_id) then
    raise exception 'Compra pertence a outro centro';
  end if;

  if cmp.status = 'recebida' then
    return cmp;
  end if;
  if cmp.status not in ('rascunho','comprado') then
    raise exception 'Compra não pode ser recebida no status atual';
  end if;
  if not exists(select 1 from public.compra_itens where compra_id=_compra_id) then
    raise exception 'Inclua ao menos um item na compra';
  end if;

  perform public.recalcular_compra(_compra_id);
  select * into cmp from public.compras where id=_compra_id for update;

  for item in
    select produto_id,
           sum(quantidade) as qtd,
           case when sum(quantidade)>0
                then sum(quantidade*custo_unitario)/sum(quantidade)
                else 0 end as custo
      from public.compra_itens
     where compra_id=_compra_id
     group by produto_id
  loop
    perform public.registrar_movimento_estoque_controlado(
      item.produto_id, cmp.centro_id, 'entrada', item.qtd, item.custo * case when cmp.total_itens>0 then cmp.total_liquido/cmp.total_itens else 1 end, -- aquisicao_218

      'compra', _compra_id, 'Entrada por NF de compra'
    );
  end loop;

  valor_parcela := round(cmp.total_liquido/greatest(coalesce(cmp.parcelas,1),1),2);
  saldo := cmp.total_liquido;

  for n in 1..greatest(coalesce(cmp.parcelas,1),1) loop
    if n = greatest(coalesce(cmp.parcelas,1),1) then
      valor_parcela := saldo;
    end if;

    insert into public.contas_pagar
      (fornecedor_id, compra_id, documento, parcela, valor, vencimento,
       centro_id, data_emissao, status)
    values
      (cmp.fornecedor_id, cmp.id,
       coalesce(nullif(cmp.nf_numero,''),'CMP-'||cmp.numero),
       n, valor_parcela,
       cmp.data_entrada + ((n-1)*30),
       cmp.centro_id, current_date, 'aberto');

    saldo := saldo - valor_parcela;
  end loop;

  update public.compras
     set status='recebida'
   where id=_compra_id
   returning * into cmp;

  insert into public.auditoria(tabela,registro_id,acao,detalhe,user_id)
  values('compras',_compra_id,'receber',
         jsonb_build_object('total',cmp.total_liquido,'centro_id',cmp.centro_id),
         auth.uid());

  return cmp;
end;
$function$
